		[894]={ skill_id=102280, skill_levelup_data={
		[8280]={ skill_lv=1, hero_rank=0, cost_item={}, need_star=0, pay_tid=0, pay_num=0, desc="When allied Operators (excluding self) release skills, they load 1 <color=#ffb136>Ammo</color> for Rose (Ammo +1 if they're same-element Operators). Max 12 stacks. When <color=#ffb136>Ammo</color> reaches full stacks, Rose enters <color=#ffb136>Full Firepower</color> (Clears debuffs) and immediately performs <color=#ffb136>Grenade Shot</color>, dealing Physical damage to all enemies equal to <color=#18ec68>100</color>% of Attack. During this state, allies cannot load Ammo for Rose, and after allies' turn (excluding self), Rose consumes 4 Ammo to perform <color=#ffb136>Covering Shot</color>, dealing Physical damage to two horizontal rows of enemy, equal to <color=#18ec68>80</color>% of Attack, and damage to main target increases by 2.5% per <color=#ffb136>Bounty</color> stack). State ends when Ammo reaches 0", skill_levelup_des="" },
		[8281]={ skill_lv=2, hero_rank=0, cost_item={}, need_star=0, pay_tid=0, pay_num=0, desc="When allied Operators (excluding self) release skills, they load 1 <color=#ffb136>Ammo</color> for Rose (Ammo +1 if they're same-element Operators). Max 12 stacks. When <color=#ffb136>Ammo</color> reaches full stacks, Rose enters <color=#ffb136>Full Firepower</color> (Clears debuffs) and immediately performs <color=#ffb136>Grenade Shot</color>, dealing Physical damage to all enemies equal to <color=#18ec68>125</color>% of Attack. During this state, allies cannot load Ammo for Rose, and after allies' turn (excluding self), Rose consumes 4 Ammo to perform <color=#ffb136>Covering Shot</color>, dealing Physical damage to two horizontal rows of enemy, equal to <color=#18ec68>90</color>% of Attack, and damage to main target increases by 2.5% per <color=#ffb136>Bounty</color> stack). State ends when Ammo reaches 0", skill_levelup_des="" },
		[8282]={ skill_lv=3, hero_rank=0, cost_item={}, need_star=0, pay_tid=0, pay_num=0, desc="When allied Operators (excluding self) release skills, they load 1 <color=#ffb136>Ammo</color> for Rose (Ammo +1 if they're same-element Operators). Max 12 stacks. When <color=#ffb136>Ammo</color> reaches full stacks, Rose enters <color=#ffb136>Full Firepower</color> (Clears debuffs) and immediately performs <color=#ffb136>Grenade Shot</color>, dealing Physical damage to all enemies equal to <color=#18ec68>150</color>% of Attack. During this state, allies cannot load Ammo for Rose, and after allies' turn (excluding self), Rose consumes 4 Ammo to perform <color=#ffb136>Covering Shot</color>, dealing Physical damage to two horizontal rows of enemy, equal to <color=#18ec68>100</color>% of Attack, and damage to main target increases by 2.5% per <color=#ffb136>Bounty</color> stack. State ends when Ammo reaches 0", skill_levelup_des="" },
