		[896]={ skill_id=102380, skill_levelup_data={
		[8286]={ skill_lv=1, hero_rank=0, cost_item={}, need_star=0, pay_tid=0, pay_num=0, desc="When allies use skills, there's a <color=#18ec68>70</color>% chance to gain 1 stack of <color=#ffb136>Abyss Resonance</color> (Max 5 stacks). When <color=#ffb136>Abyss Resonance</color> reaches max stacks, converts to <color=#ffb136>Abyss Echo</color> (<color=#ffb136>Abyss Resonance</color> cannot convert when there's <color=#ffb136>Abyss Echo</color>). If there's <color=#ffb136>Abyss Echo</color> during action, consumes <color=#ffb136>Abyss Echo</color> to enter <color=#ffb136>Abyss of Thunder</color> for 2 turns (In this state, <color=#ffb136>Abyss Resonance</color> cannot convert to <color=#ffb136>Abyss Echo</color>). Entering <color=#ffb136>Abyss of Thunder</color> grants <color=#18ec68>2</color> stacks of <color=#ffb136>Abyss Reverse</color> (when attacked by skills, consume 1 stack of <color=#ffb136>Abyss Reverse</color> for 30% damage Reduction) for 2 turns", skill_levelup_des="" },
		[8287]={ skill_lv=2, hero_rank=0, cost_item={}, need_star=0, pay_tid=0, pay_num=0, desc="When allies use skills, there's a <color=#18ec68>85</color>% chance to gain 1 stack of <color=#ffb136>Abyss Resonance</color> (Max 5 stacks). When <color=#ffb136>Abyss Resonance</color> reaches max stacks, converts to <color=#ffb136>Abyss Echo</color> (<color=#ffb136>Abyss Resonance</color> cannot convert when there's <color=#ffb136>Abyss Echo</color>). If there's <color=#ffb136>Abyss Echo</color> during action, consumes <color=#ffb136>Abyss Echo</color> to enter <color=#ffb136>Abyss of Thunder</color> for 2 turns (In this state, <color=#ffb136>Abyss Resonance</color> cannot convert to <color=#ffb136>Abyss Echo</color>). Entering <color=#ffb136>Abyss of Thunder</color> grants <color=#18ec68>2</color> stacks of <color=#ffb136>Abyss Reverse</color> (when attacked by skills, consume 1 stack of <color=#ffb136>Abyss Reverse</color> for 30% damage Reduction) for 2 turns", skill_levelup_des="" },
		[8288]={ skill_lv=3, hero_rank=0, cost_item={}, need_star=0, pay_tid=0, pay_num=0, desc="When allies use skills, there's a <color=#18ec68>100</color>% chance to gain 1 stack of <color=#ffb136>Abyss Resonance</color> (Max 5 stacks). When <color=#ffb136>Abyss Resonance</color> reaches max stacks, converts to <color=#ffb136>Abyss Echo</color> (<color=#ffb136>Abyss Resonance</color> cannot convert when there's <color=#ffb136>Abyss Echo</color>). If there's <color=#ffb136>Abyss Echo</color> during action, consumes <color=#ffb136>Abyss Echo</color> to enter <color=#ffb136>Abyss of Thunder</color> for 2 turns (In this state, <color=#ffb136>Abyss Resonance</color> cannot convert to <color=#ffb136>Abyss Echo</color>). Entering <color=#ffb136>Abyss of Thunder</color> grants <color=#18ec68>2</color> stacks of <color=#ffb136>Abyss Reverse</color> (when attacked by skills, consume 1 stack of <color=#ffb136>Abyss Reverse</color> for 30% damage Reduction) for 2 turns", skill_levelup_des="" },
} },
		[897]={ skill_id=102390, skill_levelup_data={
		[8289]={ skill_lv=1, hero_rank=0, cost_item={}, need_star=0, pay_tid=0, pay_num=0, desc="When suffering lethal damage, triggers <color=#ffb136>Cradle's Embrace</color> (during which Abyss Alicia cannot act, cannot be targeted by enemies, cannot receive healing from other sources, and becomes immune to all damage and negative effects). In this state, the acquisition rate of <color=#ffb136>Abyss Resonance</color> reduces by 50%, while allies grant Abyss Alicia 1 stack of <color=#ffb136>Abyss Return</color> each time they use a skill. If she possesses 6 stacks of <color=#ffb136>Abyss Return</color> before acting, consumes all stacks of <color=#ffb136>Abyss Return</color>to revive with <color=#18ec68>30</color>% of max HP (does not consume <color=#ffb136>Abyss Echo</color>). With fewer than 6 stacks of <color=#ffb136>Abyss Return</color>, consumes <color=#ffb136>Abyss Echo</color> to revive with <color=#18ec68>60</color>% of max HP. If revival conditions aren't met, remains in <color=#ffb136>Cradle's Embrace</color> (cannot trigger <color=#ffb136>Cradle's Embrace</color>when Abyss Alicia is the last remaining unit on the field)", skill_levelup_des="" },
		[8290]={ skill_lv=2, hero_rank=0, cost_item={}, need_star=0, pay_tid=0, pay_num=0, desc="When suffering lethal damage, triggers <color=#ffb136>Cradle's Embrace</color> (during which Abyss Alicia cannot act, cannot be targeted by enemies, cannot receive healing from other sources, and becomes immune to all damage and negative effects). In this state, the acquisition rate of <color=#ffb136>Abyss Resonance</color> reduces by 50%, while allies grant Abyss Alicia 1 stack of <color=#ffb136>Abyss Return</color> each time they use a skill. If she possesses 6 stacks of <color=#ffb136>Abyss Return</color> before acting, consumes all stacks of <color=#ffb136>Abyss Return</color>to revive with <color=#18ec68>40</color>% of max HP (does not consume <color=#ffb136>Abyss Echo</color>). With fewer than 6 stacks of <color=#ffb136>Abyss Return</color>, consumes <color=#ffb136>Abyss Echo</color> to revive with <color=#18ec68>80</color>% of max HP. If revival conditions aren't met, remains in <color=#ffb136>Cradle's Embrace</color> (cannot trigger <color=#ffb136>Cradle's Embrace</color>when Abyss Alicia is the last remaining unit on the field)", skill_levelup_des="" },
		[8291]={ skill_lv=3, hero_rank=0, cost_item={}, need_star=0, pay_tid=0, pay_num=0, desc="When suffering lethal damage, triggers <color=#ffb136>Cradle's Embrace</color> (during which Abyss Alicia cannot act, cannot be targeted by enemies, cannot receive healing from other sources, and becomes immune to all damage and negative effects). In this state, the acquisition rate of <color=#ffb136>Abyss Resonance</color> reduces by 50%, while allies grant Abyss Alicia 1 stack of <color=#ffb136>Abyss Return</color> each time they use a skill. If she possesses 6 stacks of <color=#ffb136>Abyss Return</color> before acting, consumes all stacks of <color=#ffb136>Abyss Return</color>to revive with <color=#18ec68>50</color>% of max HP (does not consume <color=#ffb136>Abyss Echo</color>). With fewer than 6 stacks of <color=#ffb136>Abyss Return</color>, consumes <color=#ffb136>Abyss Echo</color> to revive with <color=#18ec68>100</color>% of max HP. If revival conditions aren't met, remains in <color=#ffb136>Cradle's Embrace</color> (cannot trigger <color=#ffb136>Cradle's Embrace</color>when Abyss Alicia is the last remaining unit on the field)", skill_levelup_des="" },
} },
}
