		[901]={ skill_id=102590, skill_levelup_data={
		[8301]={ skill_lv=1, hero_rank=0, cost_item={}, need_star=0, pay_tid=0, pay_num=0, desc="At the start of battle, Luna creates 1 <color=#ffb136>Full Moon Radiance</color>. While Luna is on the field and has consumed 5 <color=#ffb136>Moonblades</color>, she removes all control effects from herself and activates <color=#ffb136>Moonlight Aegis</color>, taking all incoming basic attack and skill damage from enemies. The damage absorption limit of <color=#ffb136>Moonlight Aegis</color> equals the total absorbed damage from 5 <color=#ffb136>Moonblades</color> + <color=#18ec68>20</color>% of Luna's Max HP, lasting 2 turns. <color=#ffb136>Moonlight Aegis</color> prioritizes damage calculation. If exceeding its absorption limit, it shatters and negates that instance of damage. If <color=#ffb136>Moonlight Aegis</color> is reactivated during its duration, the previous instance will be replaced", skill_levelup_des="" },
		[8302]={ skill_lv=2, hero_rank=0, cost_item={}, need_star=0, pay_tid=0, pay_num=0, desc="At the start of battle, Luna creates 1 <color=#ffb136>Full Moon Radiance</color>. While Luna is on the field and has consumed 5 <color=#ffb136>Moonblades</color>, she removes all control effects from herself and activates <color=#ffb136>Moonlight Aegis</color>, taking all incoming basic attack and skill damage from enemies. The damage absorption limit of <color=#ffb136>Moonlight Aegis</color> equals the total absorbed damage from 5 <color=#ffb136>Moonblades</color> + <color=#18ec68>30</color>% of Luna's Max HP, lasting 2 turns. <color=#ffb136>Moonlight Aegis</color> prioritizes damage calculation. If exceeding its absorption limit, it shatters and negates that instance of damage. If <color=#ffb136>Moonlight Aegis</color> is reactivated during its duration, the previous instance will be replaced", skill_levelup_des="" },
		[8303]={ skill_lv=3, hero_rank=0, cost_item={}, need_star=0, pay_tid=0, pay_num=0, desc="At the start of battle, Luna creates 1 <color=#ffb136>Full Moon Radiance</color>. While Luna is on the field and has consumed 5 <color=#ffb136>Moonblades</color>, she removes all control effects from herself and activates <color=#ffb136>Moonlight Aegis</color>, taking all incoming basic attack and skill damage from enemies. The damage absorption limit of <color=#ffb136>Moonlight Aegis</color> equals the total absorbed damage from 5 <color=#ffb136>Moonblades</color> + <color=#18ec68>40</color>% of Luna's Max HP, lasting 2 turns. <color=#ffb136>Moonlight Aegis</color> prioritizes damage calculation. If exceeding its absorption limit, it shatters and negates that instance of damage. If <color=#ffb136>Moonlight Aegis</color> is reactivated during its duration, the previous instance will be replaced", skill_levelup_des="" },
