		[908]={ skill_id=102980, skill_levelup_data={
		[8322]={ skill_lv=1, hero_rank=0, cost_item={}, need_star=0, pay_tid=0, pay_num=0, desc="At the start of each turn, randomly generates 1 Static Ball (invincible, occupies an empty tile, inherits <color=#18ec68>30</color>% of Morpho's <color=#ffb136>Offensive Stats</color>) around enemies, lasting 2 turns, max 3 balls. Enemy units within the 3x3 area of a Static Ball have SPD reduced by <color=#18ec68>3</color>% × <color=#ffb136>Electrode</color> stacks and Lightning RES reduced by <color=#18ec68>4</color>% × <color=#ffb136>Electrode</color> stacks (non-stacking, only the highest value applies). At the end of each turn, Static Balls discharge to <color=#ffb136>all enemies</color>, dealing Lightning damage equal to 30% of the Ball's ATK × <color=#ffb136>Electrode</color> stacks (can CRIT and receive DMG bonuses). When Morpho acts, provides 1 stack of <color=#ffb136>Electrode</color> to Static Balls. Each Ball can store up to 4 stacks of <color=#ffb136>Electrode</color>", skill_levelup_des="" },
		[8323]={ skill_lv=2, hero_rank=0, cost_item={}, need_star=0, pay_tid=0, pay_num=0, desc="At the start of each turn, randomly generates 1 Static Ball (invincible, occupies an empty tile, inherits <color=#18ec68>37.5</color>% of Morpho's <color=#ffb136>Offensive Stats</color>) around enemies, lasting 2 turns, max 3 balls. Enemy units within the 3x3 area of a Static Ball have SPD reduced by <color=#18ec68>4</color>% × <color=#ffb136>Electrode</color> stacks and Lightning RES reduced by <color=#18ec68>5</color>% × <color=#ffb136>Electrode</color> stacks (non-stacking, only the highest value applies). At the end of each turn, Static Balls discharge to <color=#ffb136>all enemies</color>, dealing Lightning damage equal to 30% of the Ball's ATK × <color=#ffb136>Electrode</color> stacks (can CRIT and receive DMG bonuses). When Morpho acts, provides 1 stack of <color=#ffb136>Electrode</color> to Static Balls. Each Ball can store up to 4 stacks of <color=#ffb136>Electrode</color>", skill_levelup_des="" },
		[8324]={ skill_lv=3, hero_rank=0, cost_item={}, need_star=0, pay_tid=0, pay_num=0, desc="At the start of each turn, randomly generates 1 Static Ball (invincible, occupies an empty tile, inherits <color=#18ec68>45</color>% of Morpho's <color=#ffb136>Offensive Stats</color>) around enemies, lasting 2 turns, max 3 balls. Enemy units within the 3x3 area of a Static Ball have SPD reduced by <color=#18ec68>5</color>% × <color=#ffb136>Electrode</color> stacks and Lightning RES reduced by <color=#18ec68>6</color>% × <color=#ffb136>Electrode</color> stacks (non-stacking, only the highest value applies). At the end of each turn, Static Balls discharge to <color=#ffb136>all enemies</color>, dealing Lightning damage equal to 30% of the Ball's ATK × <color=#ffb136>Electrode</color> stacks (can CRIT and receive DMG bonuses). When Morpho acts, provides 1 stack of <color=#ffb136>Electrode</color> to Static Balls. Each Ball can store up to 4 stacks of <color=#ffb136>Electrode</color>", skill_levelup_des="" },
